import pytest


def match_parens(lst):
    '''
    You are given a list of two strings, both strings consist of open
    parentheses '(' or close parentheses ')' only.
    Your job is to check if it is possible to concatenate the two strings in
    some order, that the resulting string will be good.
    A string S is considered to be good if and only if all parentheses in S
    are balanced. For example: the string '(())()' is good, while the string
    '())' is not.
    Return 'Yes' if there's a way to make a good string, and return 'No' otherwise.

    Examples:
    match_parens(['()(', ')']) == 'Yes'
    match_parens([')', ')']) == 'No'
    '''
    def check(s):
        val = 0
        for i in s:
            if i == '(':
                val = val + 1
            else:
                val = val - 1
            if val < 0:
                return False
        return True if val == 0 else False

    S1 = lst[0] + lst[1]
    S2 = lst[1] + lst[0]
    return 'Yes' if check(S1) or check(S2) else 'No'


def test_match_parens_basic():
    assert match_parens(['()(', ')']) == 'Yes'


def test_match_parens_both_close():
    assert match_parens([')', ')']) == 'No'


def test_match_parens_mixed():
    assert match_parens(['(', ')']) == 'Yes'


def test_match_parens_empty():
    assert match_parens([]) == 'Yes'


def test_match_parens_single_open():
    assert match_parens(['(']) == 'No'


def test_match_parens_single_close():
    assert match_parens(['']) == 'Yes'


def test_match_parens_two_open():
    assert match_parens(['(', '(']) == 'No'


def test_match_parens_two_close():
    assert match_parens([')', ')']) == 'No'


def test_match_parens_three_open():
    assert match_parens(['(', '(', '(']) == 'No'


def test_match_parens_three_close():
    assert match_parens([')', ')', ')']) == 'No'


def test_match_parens_complex():
    assert match_parens(['((', ')(', ')']) == 'Yes'


def test_match_parens_reverse_complex():
    assert match_parens(['(', ')', ')(', '(']) == 'Yes'


def test_match_parens_empty_list():
    assert match_parens([]) == 'Yes'


def test_match_parens_single_element():
    assert match_parens(['()']) == 'Yes'
    assert match_parens(['()']) == 'Yes'
